import{_ as n,l as s,o as e,c as i,v as o,p as h,x as t,d as l,i as A,S as d}from"./chunks/framework.InCnrqk-.js";const w=JSON.parse('{"title":"Chow 断点检验","description":"","frontmatter":{"title":"Chow 断点检验","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/chow-test.md","filePath":"quant/chow-test.md","lastUpdated":1789023840000}'),E={name:"quant/chow-test.md"};function p(C,a,c,m,u,_){const r=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="chow-断点检验" tabindex="-1">Chow 断点检验 <a class="header-anchor" href="#chow-断点检验" aria-label="Permalink to &quot;Chow 断点检验&quot;">​</a></h1><div class="epigraph"><p>若斜率在某一已知日期前后不是同一组参数，把样本绑在一次回归里估的是两段体制的加权；用分段残差平方和对照，可以检验这个断裂。</p><footer>—— Chow, Tests of Equality Between Sets of Coefficients in Two Linear Regressions, Econometrica, 1960</footer></div><p><a href="/quant/state-space-kalman-smoother">Kalman 平滑</a> 让参数慢慢游走，会把真的政策日、改革日、危机日抹成斜坡。Chow 问的是<strong>已知日期</strong>上的一次性断裂：\\(\\beta\\) 在 \\(t_0\\) 前后是否相同。Andrews、Bai–Perron 把日期未知时的上确界检验与多断点写成后续。本课缺口：VAR/GARCH/HAR 的全样本系数在有断点时持续被高估、IRF 被污染。下一课 ARFIMA 处理的是缓慢衰减的记忆，容易与未建模断点互相假扮——先把断点检验钉住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线性回归，预指定 \\(t_0\\)，Chow 的 \\(F\\) 比较全样本 RSS 与两段分别 RSS。原假设：\\(\\beta_1=\\beta_2\\)。金融里 \\(t_0\\) 常常「看起来像」：金融危机、涨跌停改革、QFII、熔断。用数据找最大 \\(F\\) 再当 Chow，临界值不再是普通 \\(F\\)——那是 Andrews 的 Quandt 似然比，须用上确界分布。</p><p>问题分两层：日期已知（制度公告）用 Chow；日期未知用 QLR/Bai–Perron。把第二层假装成第一层，会过度拒绝。对象是<strong>均值方程（或给定方差模型）的参数稳定</strong>，不是波动水平的一切变化——方差断裂应有专门检验。</p><h3 id="与-cusum-的分工" tabindex="-1">与 CUSUM 的分工 <a class="header-anchor" href="#与-cusum-的分工" aria-label="Permalink to &quot;与 CUSUM 的分工&quot;">​</a></h3><p><a href="/quant/cusum-mosum">CUSUM/MOSUM</a> 对递归残差累积，善于探测逐渐漂移。Chow/QLR 善于一次性水平跳。两者应并列：改革日附近用 Chow，缓慢自由化用 CUSUM。Kalman 随机游走 \\(\\beta_t\\) 是第三种：每个时点都在变，没有「两段」。先选对象再选检验。</p><p><span class="marginnote">在最大 \\(t\\) 的那一天标断点，再讲故事，是设定搜索。预登记候选日期（官方实施日），或用 Bai–Perron 并把置信区间一起报。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>已知日期。</strong> Chow \\(F\\)；异方差用稳健 Wald 的分段版本；小样本、肥尾用自助（在原假设下抽残差，保持 GARCH 则块自助）。两段 \\(T\\) 极不对称时，短段系数方差大，\\(F\\) 功效低。</p><p><strong>未知日期。</strong> Andrews QLR：对中间 70% 样本扫 \\(t_0\\)，取最大统计量，用 Andrews 临界值。Bai–Perron 允许多个断点，用信息准则或序列检验定个数，给出日期的置信区间。残差相关时须 HAC 版本。</p><p><strong>GARCH 持续性。</strong> Lamoureux–Lastrapes：忽略方差水平的断裂会把 \\(\\alpha+\\beta\\) 推向 1。对波动模型，应允许 \\(\\omega\\) 分段，再估持续性——这是 Chow 思想在方差方程，不是把收益均值切两段就完。</p><h3 id="var-与-irf" tabindex="-1">VAR 与 IRF <a class="header-anchor" href="#var-与-irf" aria-label="Permalink to &quot;VAR 与 IRF&quot;">​</a></h3><p>全样本 VAR 在断点后 \\(\\Phi\\) 变了，IRF 是混合物。应分段估 IRF，或把断点写成已知的交互项。Granger 全样本显著若只来自一段，分段后消失——应报告。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Chow 是线性约束的 \\(F\\)：把「一段参数」对「两段参数」的拟合改善，按自由度标准化。机制要求断点外参数恒定、误差同分布。若其实是三断点，两段 Chow 会误设，RSS 改善不够或把错误 \\(t_0\\) 当断点。QLR 的机制是多重检验的上确界：在很多候选日里看最极端的 \\(F\\)，临界值因此更高。</p><p>未建模断点与长记忆的外观相似：均值或方差的几次水平跳，会让 ACF 拖尾。这就是下一课必须先做断点再谈 ARFIMA 的原因。Diebold–Inoue 等讨论过这种假长记忆。</p><p><span class="marginnote">事件研究的 \\(t=0\\) 是均值的一次跳，通常不把 \\(\\beta\\) 当断裂。Chow 的对象是斜率/截距体制，不是单日 AR。单日用事件窗，体制用分段。</span></p><h3 id="内生断点与政策" tabindex="-1">内生断点与政策 <a class="header-anchor" href="#内生断点与政策" aria-label="Permalink to &quot;内生断点与政策&quot;">​</a></h3><p>若 \\(t_0\\) 是因为 \\(y\\) 已经崩了才宣布的政策，断点内生，Chow 的分布更麻烦。应用公告准备期之外的日期，或工具化政策。这与 IV 课的排除是同一识别问题在时间上的版本。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>多重断点 + 短样本，Bai–Perron 会切出没有经济含义的碎段。异方差、GARCH、跳跃让经典 \\(F\\) 过度拒绝，须稳健或自助。面板断点（各公司不同 \\(t_0\\)）是另一文献，不要对混合 OLS 做一次 Chow 宣称「市场断了」。</p><p>工程：预登记制度日做 Chow；探索性用 QLR 并报日期置信区间；波动模型允许水平分段。不要用 Chow 替代 <a href="/quant/robust-regression-outliers">稳健回归</a> 去「删危机」。不要在同一序列上搜完断点再估 ARFIMA 还声称发现长记忆而不报告断点步骤。下一课：在断点处理之后，若 ACF 仍双曲线衰减，才轮到分整。</p>',24)),(e(),h(d,null,{default:t(()=>[A(r,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%85%A8%E6%A0%B7%E6%9C%AC%E5%9B%9E%E5%BD%92%22%5D%20--%3E%20Q%7B%22%E6%96%AD%E7%82%B9%E6%97%A5%E6%9C%9F%3F%22%7D%0A%20%20Q%20--%3E%7C%E5%B7%B2%E7%9F%A5%E5%88%B6%E5%BA%A6%E6%97%A5%7C%20CHOW%5B%22Chow%20F%20%2F%20%E7%A8%B3%E5%81%A5%20Wald%22%5D%0A%20%20Q%20--%3E%7C%E6%9C%AA%E7%9F%A5%7C%20QLR%5B%22Andrews%20QLR%20%2F%20Bai-Perron%22%5D%0A%20%20CHOW%20--%3E%20SEG%5B%22%E5%88%86%E6%AE%B5%20%CE%B2%22%5D%0A%20%20QLR%20--%3E%20SEG%0A%20%20SEG%20--%3E%20IRF%5B%22%E5%88%86%E6%AE%B5%20IRF%20%2F%20%E5%88%86%E6%AE%B5%20GARCH%20%CF%89%22%5D%0A%20%20SKIP%5B%22%E5%BF%BD%E7%95%A5%E6%96%AD%E7%82%B9%22%5D%20--%3E%20FAKE%5B%22%E5%81%87%E6%8C%81%E7%BB%AD%E6%80%A7%20%2F%20%E5%81%87%E9%95%BF%E8%AE%B0%E5%BF%86%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Chow 检验已知日期上的参数断裂；用数据搜日期须改用 QLR/Bai–Perron 的上确界临界值。</li><li>与 CUSUM（渐变）、Kalman（每期游走）对象不同，应先选机制再选检验。</li><li>忽略方差水平断裂会抬高 GARCH 持续性；忽略均值断裂会制造假长记忆外观。</li><li>内生政策日、肥尾、GARCH 都要求稳健或自助，而不是教科书 \\(F\\)。</li><li>出处：Chow, <em>Econometrica</em>, 1960；未知日期见 Andrews, <em>Econometrica</em>, 1993；多断点见 Bai and Perron, <em>Econometrica</em>, 1998。</li></ul>',2))])}const R=n(E,[["render",p]]);export{w as __pageData,R as default};
